217	        Group {
218	            #if os(iOS)
219	            DockPinnedReorderCollectionView(
220	                rows: rows,
221	                rowSpacing: rowSpacing,
222	                onReorder: onReorder,
223	                onUnpin: onUnpin,
224	                onOpen: onOpen,
225	                onHeightChange: updateMeasuredListHeight,
226	                rowContent: rowContent
227	            )
228	            .frame(height: listHeight)
229	            #else
230	            VStack(alignment: .leading, spacing: rowSpacing) {
231	                ForEach(rows) { row in
