240	    private var listHeight: CGFloat {
241	        max(1, measuredListHeight > 0 ? measuredListHeight : estimatedListHeight)
242	    }
243	
244	    private var estimatedListHeight: CGFloat {
245	        guard !rows.isEmpty else {
246	            return 1
247	        }
248	        return (CGFloat(rows.count) * estimatedRowHeight) + (CGFloat(max(0, rows.count - 1)) * rowSpacing)
249	    }
