251	    private func updateMeasuredListHeight(_ height: CGFloat) {
252	        let nextHeight = max(1, ceil(height))
253	        guard nextHeight.isFinite, abs(measuredListHeight - nextHeight) > 0.5 else {
254	            return
255	        }
256	        measuredListHeight = nextHeight
257	    }
258	}
