261	private struct DockPinnedReorderCollectionView<RowContent: View>: UIViewRepresentable {
262	    let rows: [DockRowViewModel]
263	    let rowSpacing: CGFloat
264	    let onReorder: ([DockRowViewModel]) -> Void
265	    let onUnpin: (DockRowViewModel) -> Void
266	    let onOpen: (DockRowViewModel) -> Void
267	    let onHeightChange: (CGFloat) -> Void
268	    @ViewBuilder let rowContent: (DockRowViewModel) -> RowContent
269	
270	    func makeCoordinator() -> Coordinator {
271	        Coordinator(self)
272	    }
273	
274	    func makeUIView(context: Context) -> UICollectionView {
275	        let coordinator = context.coordinator
276	        var configuration = UICollectionLayoutListConfiguration(appearance: .plain)
277	        configuration.backgroundColor = .clear
278	        configuration.showsSeparators = false
279	        configuration.trailingSwipeActionsConfigurationProvider = { indexPath in
280	            coordinator.trailingSwipeActionsConfiguration(for: indexPath)
281	        }
282	        let layout = UICollectionViewCompositionalLayout.list(using: configuration)
283	
284	        let collectionView = PinnedCollectionView(frame: .zero, collectionViewLayout: layout)
285	        collectionView.backgroundColor = .clear
286	        collectionView.alwaysBounceVertical = false
287	        collectionView.isScrollEnabled = false
288	        collectionView.showsHorizontalScrollIndicator = false
289	        collectionView.showsVerticalScrollIndicator = false
290	        collectionView.dataSource = context.coordinator
291	        collectionView.delegate = context.coordinator
292	        collectionView.register(UICollectionViewListCell.self, forCellWithReuseIdentifier: dockPinnedRowCellReuseID)
293	        collectionView.accessibilityIdentifier = AutomationID.Dock.pinnedRowsList.rawValue
294	        collectionView.onContentHeightChange = { [weak coordinator] height in
295	            coordinator?.reportMeasuredHeight(height)
296	        }
297	
298	        let longPress = UILongPressGestureRecognizer(
299	            target: context.coordinator,
300	            action: #selector(Coordinator.handleLongPress(_:))
301	        )
302	        longPress.minimumPressDuration = 0.35
303	        longPress.cancelsTouchesInView = true
304	        longPress.delegate = context.coordinator
305	        collectionView.addGestureRecognizer(longPress)
306	
307	        return collectionView
308	    }
309	
310	    func updateUIView(_ collectionView: UICollectionView, context: Context) {
311	        context.coordinator.parent = self
312	        guard !context.coordinator.isMoving else {
313	            return
314	        }
315	        context.coordinator.workingRows = rows
316	        collectionView.reloadData()
317	        collectionView.collectionViewLayout.invalidateLayout()
318	        collectionView.setNeedsLayout()
319	        collectionView.layoutIfNeeded()
320	        context.coordinator.reportMeasuredHeight(collectionView.collectionViewLayout.collectionViewContentSize.height)
321	    }
322	
323	    final class PinnedCollectionView: UICollectionView {
324	        var onContentHeightChange: ((CGFloat) -> Void)?
325	        private var lastContentHeight: CGFloat = 0
326	
327	        override func layoutSubviews() {
328	            super.layoutSubviews()
329	            let height = collectionViewLayout.collectionViewContentSize.height
330	            guard height.isFinite, abs(height - lastContentHeight) > 0.5 else {
331	                return
332	            }
333	            lastContentHeight = height
334	            onContentHeightChange?(height)
335	        }
336	    }
337	
338	    final class Coordinator: NSObject, UICollectionViewDataSource, UICollectionViewDelegate, UIGestureRecognizerDelegate {
339	        var parent: DockPinnedReorderCollectionView
340	        var workingRows: [DockRowViewModel]
341	        var isMoving = false
342	        private var lastReportedHeight: CGFloat = 0
343	
344	        init(_ parent: DockPinnedReorderCollectionView) {
345	            self.parent = parent
346	            self.workingRows = parent.rows
347	        }
348	
349	        func reportMeasuredHeight(_ height: CGFloat) {
350	            guard height.isFinite, abs(height - lastReportedHeight) > 0.5 else {
351	                return
352	            }
353	            lastReportedHeight = height
354	            DispatchQueue.main.async { [weak self] in
355	                self?.parent.onHeightChange(height)
356	            }
357	        }
358	
359	        func collectionView(_ collectionView: UICollectionView, numberOfItemsInSection section: Int) -> Int {
360	            workingRows.count
361	        }
362	
363	        func collectionView(
364	            _ collectionView: UICollectionView,
365	            cellForItemAt indexPath: IndexPath
366	        ) -> UICollectionViewCell {
367	            let cell = collectionView.dequeueReusableCell(
368	                withReuseIdentifier: dockPinnedRowCellReuseID,
369	                for: indexPath
370	            )
371	            guard let cell = cell as? UICollectionViewListCell else {
372	                return cell
373	            }
374	            cell.contentConfiguration = nil
375	            cell.backgroundColor = .clear
376	            cell.contentView.backgroundColor = .clear
377	            cell.backgroundConfiguration = .clear()
378	
379	            guard indexPath.item < workingRows.count else {
380	                return cell
381	            }
382	
383	            let row = workingRows[indexPath.item]
384	            cell.contentConfiguration = UIHostingConfiguration {
385	                parent.rowContent(row)
386	                    .padding(.vertical, parent.rowSpacing / 2)
387	                    .frame(maxWidth: .infinity, alignment: .topLeading)
388	            }
389	            .margins(.all, 0)
390	            return cell
391	        }
392	
393	        func collectionView(_ collectionView: UICollectionView, canMoveItemAt indexPath: IndexPath) -> Bool {
394	            indexPath.item < workingRows.count
395	        }
396	
397	        func collectionView(_ collectionView: UICollectionView, didSelectItemAt indexPath: IndexPath) {
398	            guard indexPath.item < workingRows.count else {
399	                return
400	            }
401	            parent.onOpen(workingRows[indexPath.item])
402	        }
403	
404	        func collectionView(
405	            _ collectionView: UICollectionView,
406	            moveItemAt sourceIndexPath: IndexPath,
407	            to destinationIndexPath: IndexPath
408	        ) {
409	            guard sourceIndexPath.item != destinationIndexPath.item,
410	                  sourceIndexPath.item < workingRows.count else {
411	                return
412	            }
413	
414	            let row = workingRows.remove(at: sourceIndexPath.item)
415	            let insertionIndex = Swift.max(0, Swift.min(workingRows.count, destinationIndexPath.item))
416	            workingRows.insert(row, at: insertionIndex)
417	        }
418	
419	        func trailingSwipeActionsConfiguration(for indexPath: IndexPath) -> UISwipeActionsConfiguration? {
420	            guard indexPath.item < workingRows.count else {
421	                return nil
422	            }
423	
424	            let row = workingRows[indexPath.item]
425	            let action = UIContextualAction(style: .destructive, title: "Unpin") { [weak self] _, _, completion in
426	                self?.parent.onUnpin(row)
427	                completion(true)
428	            }
429	            action.image = UIImage(systemName: "pin.slash")
430	
431	            let configuration = UISwipeActionsConfiguration(actions: [action])
432	            configuration.performsFirstActionWithFullSwipe = true
433	            return configuration
434	        }
435	
436	        @objc func handleLongPress(_ gesture: UILongPressGestureRecognizer) {
437	            guard let collectionView = gesture.view as? UICollectionView else {
438	                return
439	            }
440	
441	            let location = gesture.location(in: collectionView)
442	            switch gesture.state {
443	            case .began:
444	                guard let indexPath = collectionView.indexPathForItem(at: location) else {
445	                    return
446	                }
447	                workingRows = parent.rows
448	                guard collectionView.beginInteractiveMovementForItem(at: indexPath) else {
449	                    isMoving = false
450	                    workingRows = parent.rows
451	                    return
452	                }
453	                isMoving = true
454	            case .changed:
455	                guard isMoving else {
456	                    return
457	                }
458	                collectionView.updateInteractiveMovementTargetPosition(location)
459	            case .ended:
460	                guard isMoving else {
461	                    return
462	                }
463	                collectionView.endInteractiveMovement()
464	                isMoving = false
465	                parent.onReorder(workingRows)
466	            default:
467	                collectionView.cancelInteractiveMovement()
468	                isMoving = false
469	                workingRows = parent.rows
470	            }
471	        }
472	
473	        func gestureRecognizer(
474	            _ gestureRecognizer: UIGestureRecognizer,
475	            shouldRecognizeSimultaneouslyWith otherGestureRecognizer: UIGestureRecognizer
476	        ) -> Bool {
477	            if gestureRecognizer is UILongPressGestureRecognizer
478	                || otherGestureRecognizer is UILongPressGestureRecognizer {
479	                return false
480	            }
481	            return true
482	        }
483	    }
484	}
485	#endif
