131	    mutating func applyUpdate(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
132	        guard update.kind != .snapshot else {
133	            return applySnapshot(update, host: host)
134	        }
135	
136	        guard acceptsSchemaVersion(update.schemaVersion) else {
137	            return .needsResync(.schemaMismatch)
138	        }
139	        guard var state = statesByHostID[host.id],
140	              state.epoch == update.epoch else {
141	            return .needsResync(.epochMismatch)
142	        }
143	        guard acceptsStreamContract(update, expectedSourceHostID: state.sourceHostID) else {
144	            return .needsResync(.streamContract)
145	        }
146	        guard acceptsProjectionSourceContinuity(update.rows ?? [], existingCardsByID: state.cardsByID) else {
147	            return .needsResync(.streamContract)
148	        }
149	        switch update.kind {
150	        case .heartbeat:
151	            guard state.seq == update.seq else {
152	                return .needsResync(.sequenceGap)
153	            }
154	        case .upsert, .delete:
155	            guard update.seq == state.seq + 1 else {
156	                return .needsResync(.sequenceGap)
157	            }
158	            for projectionID in update.projectionIDs ?? [] {
159	                state.cardsByID.removeValue(forKey: projectionID)
160	            }
161	            for card in (update.rows ?? []).filter(\.isAppFacingHumanThreadCard) {
162	                state.cardsByID[card.projectionStorageKey] = card
163	            }
164	            state.seq = update.seq
165	        case .resyncRequired:
166	            return .needsResync(.streamContract)
167	        case .snapshot:
168	            break
169	        }
170	
171	        state.freshness = update.freshness
172	        state.complete = update.complete ?? state.complete
173	        state.totalRows = update.totalRows ?? state.totalRows
174	        state.window = update.window ?? state.window
175	        state.status = hostStatus(
176	            freshness: state.freshness,
177	            rowCount: state.cardsByID.count,
178	            complete: state.complete,
179	            totalRows: state.totalRows
180	        )
181	        statesByHostID[host.id] = state
182	        return .applied
183	    }
