189	    private func acceptsStreamContract(
190	        _ update: ThreadCardStreamUpdateDTO,
191	        expectedSourceHostID: String? = nil
192	    ) -> Bool {
193	        guard let sourceHostID = nonEmpty(update.sourceHostID),
194	              update.identityVersion == ProjectionEnvelope.identityVersion,
195	              update.projectionEngineVersion == ProjectionEnvelope.engineVersion,
196	              update.scope == ProjectionEnvelope.scope,
197	              nonEmpty(update.viewParamsKey) != nil,
198	              update.order == ProjectionEnvelope.order else {
199	            return false
200	        }
201	        if let expectedSourceHostID,
202	           expectedSourceHostID != sourceHostID {
203	            return false
204	        }
205	        guard update.view == expectedView else {
206	            return false
207	        }
208	        switch update.kind {
209	        case .snapshot:
210	            guard let complete = update.complete,
211	                  let totalRows = update.totalRows,
212	                  let window = update.window else {
213	                return false
214	            }
215	            return acceptsWindowContract(
216	                complete: complete,
217	                totalRows: totalRows,
218	                window: window,
219	                    cardCount: update.rows?.count ?? 0
220	            )
221	                && acceptsProjectionEnvelope(update.rows ?? [], sourceHostID: sourceHostID)
222	        case .upsert, .delete, .heartbeat, .resyncRequired:
223	            guard acceptsProjectionEnvelope(update.rows ?? [], sourceHostID: sourceHostID),
224	                  acceptsDeleteIDs(update.projectionIDs ?? []) else {
225	                return false
226	            }
227	            if update.complete == false {
228	                guard let totalRows = update.totalRows,
229	                      let window = update.window else {
230	                    return false
231	                }
232	                return acceptsWindowContract(
233	                    complete: false,
234	                    totalRows: totalRows,
235	                    window: window,
236	                    cardCount: update.rows?.count ?? 0
237	                )
238	            }
239	            return true
240	        }
241	    }
