243	    private func acceptsWindowContract(
244	        complete: Bool,
245	        totalRows: Int,
246	        window: DockStreamWindowDTO,
247	        cardCount: Int
248	    ) -> Bool {
249	        guard totalRows >= 0,
250	              window.offset >= 0,
251	              window.limit >= 0,
252	              window.rowCount >= 0,
253	              window.rowCount == cardCount else {
254	            return false
255	        }
256	        if let nextOffset = window.nextOffset,
257	           nextOffset <= window.offset {
258	            return false
259	        }
260	        return complete || window.rowCount <= totalRows
261	    }
