263	    private func acceptsProjectionEnvelope(_ cards: [DockThreadCardDTO], sourceHostID expectedSourceHostID: String) -> Bool {
264	        var seenProjectionIDs = Set<String>()
265	        var seenSourceKeys = Set<ThreadCardProjectionSourceKey>()
266	        for card in cards {
267	            guard let sourceHostID = nonEmpty(card.sourceHostID) else {
268	                return false
269	            }
270	            guard card.schemaVersion == ProjectionEnvelope.schemaVersion
271	                && card.identityVersion == ProjectionEnvelope.identityVersion
272	                && card.projectionEngineVersion == ProjectionEnvelope.engineVersion
273	                && sourceHostID == expectedSourceHostID
274	                && card.logicalHostID == sourceHostID
275	                && card.view == expectedView.rawValue
276	                && nonEmpty(card.projectionID) != nil
277	                && card.id == card.projectionID
278	                && nonEmpty(card.sourceRef) != nil
279	                && card.rowRole == ProjectionEnvelope.rowRole
280	                && nonEmpty(card.displayOrderKey) != nil else {
281	                return false
282	            }
283	            guard seenProjectionIDs.insert(card.projectionID).inserted else {
284	                return false
285	            }
286	            guard seenSourceKeys.insert(ThreadCardProjectionSourceKey(card)).inserted else {
287	                return false
288	            }
289	        }
290	        return true
291	    }
