293	    private func acceptsProjectionSourceContinuity(
294	        _ cards: [DockThreadCardDTO],
295	        existingCardsByID: [String: DockThreadCardDTO]
296	    ) -> Bool {
297	        var existingProjectionIDsBySourceKey = [ThreadCardProjectionSourceKey: String]()
298	        for card in existingCardsByID.values {
299	            let sourceKey = ThreadCardProjectionSourceKey(card)
300	            if existingProjectionIDsBySourceKey.updateValue(card.projectionStorageKey, forKey: sourceKey) != nil {
301	                return false
302	            }
303	        }
304	        for card in cards {
305	            let sourceKey = ThreadCardProjectionSourceKey(card)
306	            if let existing = existingCardsByID[card.projectionStorageKey],
307	               ThreadCardProjectionSourceKey(existing) != sourceKey {
308	                return false
309	            }
310	            if let existingProjectionID = existingProjectionIDsBySourceKey[sourceKey],
311	               existingProjectionID != card.projectionStorageKey {
312	                return false
313	            }
314	        }
315	        return true
316	    }
