384	    private func sortedCards(for host: DockHostConfiguration) -> [DockThreadCardDTO] {
385	        guard let state = statesByHostID[host.id] else {
386	            return []
387	        }
388	        return Array(state.cardsByID.values)
389	            .sorted { lhs, rhs in
390	                if lhs.displayOrderKey != rhs.displayOrderKey {
391	                    return lhs.displayOrderKey < rhs.displayOrderKey
392	                }
393	                return lhs.projectionStorageKey < rhs.projectionStorageKey
394	            }
