397	    private func identityObservations(hosts: [DockHostConfiguration]) -> [DockHostIdentityObservation] {
398	        hosts.flatMap { host in
399	            guard let state = statesByHostID[host.id] else {
400	                return [DockHostIdentityObservation]()
401	            }
402	            var observations = [DockHostIdentityObservation(
403	                configuredHostID: host.id,
404	                streamHostID: state.sourceHostID
405	            )]
406	            let cardObservations = state.cardsByID.values.map { card in
407	                DockHostIdentityObservation(configuredHostID: host.id, card: card)
408	            }
409	            observations.append(contentsOf: cardObservations)
410	            return observations
411	        }
