60	public struct RelayDiagnosticsClient: Sendable {
61	    private let session: URLSession
62	    private let decoder: JSONDecoder
63	
64	    public init(session: URLSession = .shared) {
65	        self.session = session
66	        self.decoder = RelayDiagnosticsDate.decoder()
67	    }
68	
69	    public func diagnosticsURL(for endpoint: DockRelayEndpoint, path requestedPath: String) throws -> URL {
70	        let baseURL = endpoint.statusURL
71	        guard baseURL.path == "/statusz" else {
72	            throw RelayDiagnosticsClientError.invalidStatusURL(baseURL)
73	        }
74	        var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false)
75	        components?.path = requestedPath.hasPrefix("/") ? requestedPath : "/\(requestedPath)"
76	        components?.query = nil
77	        components?.fragment = nil
78	        guard let url = components?.url else {
79	            throw RelayDiagnosticsClientError.invalidStatusURL(baseURL)
80	        }
81	        return url
82	    }
83	
84	    public func fetchRoutes(for endpoint: DockRelayEndpoint) async throws -> [RouteDiagnosticSnapshot] {
85	        let url = try diagnosticsURL(for: endpoint, path: "/routesz")
86	        let response: RelayDiagnosticsRoutesResponse = try await fetch(url)
87	        return response.routes.map { $0.snapshot(fallbackConfiguredHostID: endpoint.id) }
88	    }
89	
90	    public func fetchStatus(for endpoint: DockRelayEndpoint) async throws -> JSONValue {
91	        try await fetchJSONValue(try diagnosticsURL(for: endpoint, path: "/statusz"))
92	    }
93	
94	    private func fetch<Response: Decodable>(_ url: URL) async throws -> Response {
95	        let (data, response) = try await session.data(from: url)
96	        guard let httpResponse = response as? HTTPURLResponse,
97	              (200..<300).contains(httpResponse.statusCode) else {
98	            throw RelayDiagnosticsClientError.requestFailed((response as? HTTPURLResponse)?.statusCode ?? -1)
99	        }
100	        return try decoder.decode(Response.self, from: data)
101	    }
102	
103	    private func fetchJSONValue(_ url: URL) async throws -> JSONValue {
104	        let (data, response) = try await session.data(from: url)
105	        guard let httpResponse = response as? HTTPURLResponse,
106	              (200..<300).contains(httpResponse.statusCode) else {
107	            throw RelayDiagnosticsClientError.requestFailed((response as? HTTPURLResponse)?.statusCode ?? -1)
108	        }
109	        return try decoder.decode(JSONValue.self, from: data)
110	    }
111	}
112	
113	private enum RelayDiagnosticsDate {
114	    static func decoder() -> JSONDecoder {
115	        let decoder = JSONDecoder()
116	        decoder.dateDecodingStrategy = .custom { decoder in
117	            let container = try decoder.singleValueContainer()
118	            let rawValue = try container.decode(String.self)
119	            if let date = parse(rawValue) {
120	                return date
121	            }
122	            throw DecodingError.dataCorruptedError(
123	                in: container,
124	                debugDescription: "Invalid relay diagnostics timestamp: \(rawValue)"
125	            )
126	        }
127	        return decoder
128	    }
129	
130	    private static func parse(_ rawValue: String) -> Date? {
131	        let fractionalFormatter = ISO8601DateFormatter()
132	        fractionalFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
133	        if let date = fractionalFormatter.date(from: rawValue) {
134	            return date
135	        }
136	
137	        let standardFormatter = ISO8601DateFormatter()
138	        standardFormatter.formatOptions = [.withInternetDateTime]
139	        return standardFormatter.date(from: rawValue)
140	    }
141	}
