2	import fs from "node:fs";
3	import process from "node:process";
4	import { pathToFileURL } from "node:url";
5	
6	import {
7	  assertProofReport,
8	  finalizeProofReport,
9	  loadProofSchemas,
10	  sampleProofReports,
11	  validateProofReport,
12	} from "./proof-report-contracts.mjs";
13	
14	function usage() {
15	  return [
16	    "Usage:",
17	    "  node scripts/check-proof-report-contracts.mjs [report.json ...]",
18	    "",
19	    "With no report paths, compiles every proof schema and validates canonical samples.",
20	    "With report paths, validates each report against its schema and semantic guardrails.",
21	  ].join("\n");
22	}
23	
24	function readReport(filePath) {
25	  return JSON.parse(fs.readFileSync(filePath, "utf8"));
26	}
27	
28	function main(argv = process.argv.slice(2)) {
29	  if (argv.includes("--help") || argv.includes("-h")) {
30	    console.log(usage());
31	    return;
32	  }
33	
34	  const validators = loadProofSchemas();
35	  const paths = argv.filter((arg) => !arg.startsWith("-"));
36	  if (!paths.length) {
37	    for (const report of sampleProofReports()) {
38	      assertProofReport(finalizeProofReport(report), {
39	        validators,
40	        sourcePath: `<sample:${report.kind}>`,
41	      });
42	    }
43	    console.log(`validated ${validators.size} proof schemas and ${sampleProofReports().length} canonical samples`);
44	    return;
45	  }
46	
47	  const errors = [];
48	  for (const filePath of paths) {
49	    const report = readReport(filePath);
50	    errors.push(...validateProofReport(report, { validators, sourcePath: filePath }));
51	  }
52	  if (errors.length) {
53	    throw new Error(errors.join("\n"));
54	  }
55	  console.log(`validated ${paths.length} proof reports`);
56	}
57	
58	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
59	  try {
60	    main();
61	  } catch (error) {
62	    console.error(`proof report contract check failed: ${error.message || error}`);
63	    process.exit(1);
64	  }
65	}
