116	function routeSetFromReport(report) {
117	  const routes = new Set();
118	  for (const route of report?.clientPathEvidence?.routes || []) {
119	    routes.add(route);
120	  }
121	  for (const route of Object.keys(report?.clientPathEvidence?.routeCounts || {})) {
122	    routes.add(route);
123	  }
124	  for (const route of Object.keys(report?.summary?.clientPathRouteCounts || {})) {
125	    routes.add(route);
126	  }
127	  const relayRoutes = report?.relayReport?.clientPathRoutes
128	    || report?.relayReport?.clientPathEvidence?.routes
129	    || [];
130	  for (const route of relayRoutes) {
131	    routes.add(route);
132	  }
133	  for (const route of Object.keys(report?.relayReport?.routeCounts || {})) {
134	    routes.add(route);
135	  }
136	  return routes;
137	}
