139	function semanticProofErrors(report) {
140	  const errors = [];
141	  const status = proofStatusForReport(report);
142	  if (report?.status !== status) {
143	    errors.push(`status must be ${status} for summary.ok=${String(report?.summary?.ok)}`);
144	  }
145	  if (status === "pass" && report?.summary?.ok === false) {
146	    errors.push("status pass cannot pair with summary.ok=false");
147	  }
148	  if (status === "fail" && report?.summary?.ok === true) {
149	    errors.push("status fail cannot pair with summary.ok=true");
150	  }
151	  for (const value of collectStrings(report)) {
152	    if (/^wss?:\/\/[^/]*:4500(?:\/|$)/u.test(value)) {
153	      errors.push(`raw app-server endpoint cannot satisfy proof: ${value}`);
154	    }
155	    if (value.includes("CODEX_DOCK_UI_DOCK_STREAM_SCENARIO")) {
156	      errors.push("scripted Dock stream scenario cannot satisfy live-update proof");
157	    }
158	  }
159	  const forbiddenKeyHits = collectForbiddenKeys(report);
160	  if (forbiddenKeyHits.length > 0) {
161	    errors.push(`proof report contains legacy identity/stream keys: ${forbiddenKeyHits.slice(0, 20).join(", ")}`);
162	  }
163	  const routes = routeSetFromReport(report);
164	  if (status === "pass" && PASSING_PROOF_KINDS_REQUIRE_ROUTES.has(report?.kind) && routes.size === 0) {
165	    errors.push("passing live-update proof must include relay-owned client route evidence");
166	  }
167	  if (status === "pass" && routes.size > 0) {
168	    const hasClientCardRoute = [...routes].some((route) => CLIENT_CARD_ROUTES.has(route));
169	    if (!hasClientCardRoute) {
170	      errors.push("passing proof must include relay-owned Dock, Archive, or Thread Detail client routes");
171	    }
172	  }
173	  if (
174	    report?.kind === "codex-dock-simulator-ui-sync-proof"
175	    && report?.proofRunID
176	    && report?.relayReport?.proofRunID
177	    && report.proofRunID !== report.relayReport.proofRunID
178	  ) {
179	    errors.push("simulator UI proofRunID must match embedded relay proofRunID");
180	  }
181	  return errors;
182	}
183	
184	function validateProofReport(report, {
185	  validators = loadProofSchemas(),
186	  sourcePath = "<report>",
187	} = {}) {
188	  const kind = report?.kind;
189	  const validate = validators.get(kind);
190	  const errors = [];
191	  if (!validate) {
192	    errors.push(`unsupported proof report kind ${kind || "missing"} at ${sourcePath}`);
193	    return errors;
194	  }
195	  if (!validate(report)) {
196	    for (const error of validate.errors || []) {
197	      errors.push(`${sourcePath}${error.instancePath || ""}: ${error.message}`);
198	    }
199	  }
200	  errors.push(...semanticProofErrors(report).map((message) => `${sourcePath}: ${message}`));
201	  return errors;
202	}
203	
204	function assertProofReport(report, options = {}) {
205	  const errors = validateProofReport(report, options);
206	  if (errors.length) {
207	    throw new Error(`proof report contract failed:\n${errors.join("\n")}`);
208	  }
209	  return report;
210	}
