    func renderInput(hosts: [DockHostConfiguration]) -> DockRenderInput {
        let hostStates = hosts.map { host in
            DockHostStateViewModel(
                host: DockHostViewModel(host: host),
                status: statesByHostID[host.id]?.status ?? .checking
            )
        }
        let statuses = Dictionary(
            uniqueKeysWithValues: hostStates.map { ($0.host.id, $0.status) }
        )
        return DockRenderInput(
            hosts: hosts,
            hostStates: hostStates,
            hostIdentityResolver: DockHostIdentityResolver(
                hosts: hosts,
                observations: identityObservations(hosts: hosts),
                hostStatuses: statuses
            ),
            cardsByHostID: Dictionary(
                uniqueKeysWithValues: hosts.map { host in
                    (host.id, sortedCards(for: host))
                }
            ),
            isPartial: hosts.contains(where: isCheckingOrPartial)
        )
    }

    func rowCount(for host: DockHostConfiguration) -> Int {
        statesByHostID[host.id]?.cardsByID.count ?? 0
    }

    func hostIdentityResolver(hosts: [DockHostConfiguration]) -> DockHostIdentityResolver {
        DockHostIdentityResolver(
            hosts: hosts,
            observations: identityObservations(hosts: hosts),
            hostStatuses: Dictionary(
                uniqueKeysWithValues: hosts.map { host in
                    (host.id, statesByHostID[host.id]?.status ?? .checking)
                }
            )
        )
    }

    private func sortedCards(for host: DockHostConfiguration) -> [DockThreadCardDTO] {
        guard let state = statesByHostID[host.id] else {
            return []
        }
        return Array(state.cardsByID.values)
            .sorted { lhs, rhs in
                if lhs.displayOrderKey != rhs.displayOrderKey {
                    return lhs.displayOrderKey < rhs.displayOrderKey
                }
                return lhs.projectionStorageKey < rhs.projectionStorageKey
            }
    }

    private func identityObservations(hosts: [DockHostConfiguration]) -> [DockHostIdentityObservation] {
        hosts.flatMap { host in
            guard let state = statesByHostID[host.id] else {
                return [DockHostIdentityObservation]()
            }
            var observations = [DockHostIdentityObservation(
                configuredHostID: host.id,
                streamHostID: state.sourceHostID
            )]
            let cardObservations = state.cardsByID.values.map { card in
                DockHostIdentityObservation(configuredHostID: host.id, card: card)
            }
            observations.append(contentsOf: cardObservations)
            return observations
        }
    }

    private func isCheckingOrPartial(_ host: DockHostConfiguration) -> Bool {
        let status = statesByHostID[host.id]?.status
        if case .checking = status {
            return true
        }
        return status?.isPartial == true
    }

    private func hostStatus(
        freshness: DockStreamFreshnessDTO?,
        rowCount: Int,
        complete: Bool,
        totalRows: Int?
    ) -> DockHostLoadStatus {
        if !complete {
            let visibleRows = rowCount
            let knownTotal = max(totalRows ?? visibleRows, visibleRows)
            let message = knownTotal > visibleRows
                ? "Showing \(visibleRows) of \(knownTotal)"
                : "Partial window"
            return .partial(rowCount: visibleRows, message: message)
        }
        guard let freshness else {
            return rowCount == 0 ? .checking : .loaded(rowCount: rowCount)
        }
        switch freshness.status {
        case .fresh:
            return rowCount == 0 ? .empty : .loaded(rowCount: rowCount)
        case .stale:
            return .partial(rowCount: rowCount, message: freshness.lastError ?? "Stale")
        case .offline:
            let message = freshness.lastError ?? "Offline"
            return rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
        case .error:
            let message = freshness.lastError ?? "Error"
            return rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
        case .unknown:
            return rowCount == 0 ? .checking : .partial(rowCount: rowCount, message: "Refreshing")
        }
    }

}

private struct ThreadCardProjectionSourceKey: Hashable, Sendable {
    let sourceHostID: String
    let view: String
    let sourceRef: String
    let rowRole: String

    init(_ card: DockThreadCardDTO) {
        sourceHostID = card.sourceHostID
        view = card.view
        sourceRef = card.sourceRef
        rowRole = card.rowRole
    }
}

import Foundation

public struct SystemHealthProjector: Sendable {
    public init() {}

    public func snapshot(
        hosts: [HostConnectivitySnapshot],
        overallStatus: AppConnectivityOverallStatus
    ) -> SystemHealthSnapshot {
        SystemHealthSnapshot(
            summary: overallStatus,
            categories: SystemHealthCategory.allCases.map { category in
                SystemHealthCategorySnapshot(
                    category: category,
                    status: status(for: category, hosts: hosts, overallStatus: overallStatus)
                )
            },
            hosts: hosts
        )
    }

    private func status(
        for category: SystemHealthCategory,
        hosts: [HostConnectivitySnapshot],
        overallStatus: AppConnectivityOverallStatus
    ) -> SystemHealthCategoryStatus {
        if hosts.isEmpty {
            return .notChecked("No relay host is configured.")
        }

        let routeNames = routeNames(for: category)
        let diagnostics = hosts.flatMap(\.routeDiagnostics).filter { routeNames.contains($0.route) }
        if diagnostics.isEmpty {
            return fallbackStatus(for: category, overallStatus: overallStatus)
        }

        if let failed = diagnostics.first(where: { diagnostic in
            diagnostic.routeStatus == .failed || diagnostic.routeStatus == .blocked
        }) {
            return .failed(
                failed.statusReasons.first?.message ?? "\(category.title) is failing.",
                nextAction: "Run check or open host details."
            )
        }

        if let degraded = diagnostics.first(where: { diagnostic in
            diagnostic.routeStatus == .degraded || diagnostic.routeStatus == .partial || diagnostic.routeStatus == .stale
        }) {
            return .degraded(
                degraded.statusReasons.first?.message ?? "\(category.title) has partial or stale evidence.",
                nextAction: "Run check or review technical details."
            )
        }

        if diagnostics.contains(where: { $0.routeStatus == .healthy }) {
            return .healthy("\(category.title) route evidence is healthy.")
        }

        return .notChecked("No completed check for \(category.title.lowercased()).")
    }

    private func fallbackStatus(
        for category: SystemHealthCategory,
        overallStatus: AppConnectivityOverallStatus
    ) -> SystemHealthCategoryStatus {
        switch overallStatus {
        case .checking, .reconnecting, .resuming:
            return .checking("Checking relay health.")
        case .online:
            switch category {
            case .dockFeed:
                return .healthy("Dock feed is receiving app evidence.")
            case .diagnostics:
                return .healthy("Relay process is reachable.")
            case .threadDetail, .archive, .voice:
                return .notChecked("No recent \(category.title.lowercased()) evidence.")
            }
        case .partial(let message):
            return .degraded(message, nextAction: "Run check or open host details.")
        case .offline(let message), .error(let message), .configurationError(let message), .unconfigured(let message):
            return .failed(message, nextAction: "Open Relay Settings.")
        case .backgrounded(let message):
            return .stale(message, nextAction: "Bring the app foreground to refresh.")
        case .stale(let message):
            return .stale(message, nextAction: "Run check.")
        }
    }

    private func routeNames(for category: SystemHealthCategory) -> Set<String> {
        switch category {
        case .dockFeed:
            return [AppServerMethods.dockSubscribe, AppServerMethods.dockUpdate, AppServerMethods.dockResync]
        case .threadDetail:
            return [
                AppServerMethods.threadDetailSubscribe,
                AppServerMethods.threadDetailUpdate,
                AppServerMethods.threadDetailResync,
            ]
        case .archive:
            return [
                AppServerMethods.archiveSubscribe,
                AppServerMethods.archiveUpdate,
                AppServerMethods.archiveResync,
                AppServerMethods.threadArchive,
                AppServerMethods.threadUnarchive
            ]
        case .voice:
            return [
                AppServerMethods.audioTranscriptionStart,
                AppServerMethods.audioTranscriptionAppend,
                AppServerMethods.audioTranscriptionCommit,
                AppServerMethods.audioTranscriptionCompleted
            ]
        case .diagnostics:
            return [AppServerMethods.initialize, AppServerMethods.initialized]
        }
    }
}

